handleMovement(cursors: Phaser.Types.Input.Keyboard.CursorKeys) {
  const speed = 100;
  this.body.setVelocity(0);

  if (cursors.left.isDown) {
    this.body.setVelocityX(-speed);
    this.anims.play('walk-left', true);
  } else if (cursors.right.isDown) {
    this.body.setVelocityX(speed);
    this.anims.play('walk-right', true);
  } else if (cursors.up.isDown) {
    this.body.setVelocityY(-speed);
    this.anims.play('walk-up', true);
  } else if (cursors.down.isDown) {
    this.body.setVelocityY(speed);
    this.anims.play('walk-down', true);
  } else {
    this.anims.stop();
  }
}

processChoice(choiceIndex: number): void {
  const currentNode = this.tree[this.currentNodeId];
  if (!currentNode || !currentNode.choices) return;

  const choice = currentNode.choices[choiceIndex];
  if (!choice) return;

  if (choice.nextNodeId) {
    this.currentNodeId = choice.nextNodeId;
    this.eventEmitter.emit('node-change', this.getCurrentNode());
  } else {
    this.eventEmitter.emit('dialogue-end');
  }
}

router.get('/stats', async (req, res) => {
