router.post('/validate', async (req, res) => {
  const { code } = req.body;
  const pass = await Pass.findOne({ code, isActive: true });

  if (!pass) {
    return res.json({ valid: false, error: 'Invalid code' });
  }

  if (pass.expiresAt && pass.expiresAt < new Date()) {
    return res.json({ valid: false, error: 'Code expired' });
  }

  const token = jwt.sign(
    { passCode: code, type: 'guest' },
    process.env.JWT_SECRET!,
    { expiresIn: '7d' }
  );

  res.json({ valid: true, token });
});

setupCamera(player: Phaser.Physics.Arcade.Sprite): void {
  this.cameras.main.startFollow(player, true, 0.1, 0.1);
  this.cameras.main.setZoom(2.0);

  const mapWidth = this.map.widthInPixels;
  const mapHeight = this.map.heightInPixels;

  this.cameras.main.setBounds(0, 0, mapWidth, mapHeight);
  this.physics.world.setBounds(0, 0, mapWidth, mapHeight);
}

private revealNextCharacter(): void {
  this.currentCharIndex++;
  this.typewriterText.setText(
    this.fullText.substring(0, this.currentCharIndex)
  );

  if (this.currentCharIndex === this.fullText.length) {
    this.time.delayedCall(1000, () => {
      this.showEnterButton();
    });
  }
}

setupCollisions(): void {
  const collisionLayer = this.map.getLayer('Collision');
  if (!collisionLayer) return;

  collisionLayer.tilemapLayer.setCollisionByProperty(
    { collides: true }
  );

  this.physics.add.collider(
    this.player,
    collisionLayer.tilemapLayer
  );
}

checkInteraction(playerX: number, playerY: number): NPC | null {
  const interactionRadius = 32;

  for (const npc of this.npcs) {
    const distance = Phaser.Math.Distance.Between(
      playerX, playerY,
      npc.x, npc.y
    );

    if (distance < interactionRadius) {
      return npc;
    }
  }

  return null;
}

navigateToApp(
  buildingId: string,
  playerX: number,
  playerY: number,
  route: string,
  isExternal: boolean
): void {
  localStorage.setItem('returnToWorld', JSON.stringify({
    buildingId,
    position: { x: playerX, y: playerY }
  }));

  if (isExternal) {
    window.open(route, '_blank');
  } else {
    this.router.navigate([route]);
  }
}

transitionToDoorScene(): void {
  const fadeOut = this.add.rectangle(
    0, 0, width, height, 0x000000
  ).setOrigin(0, 0).setAlpha(0).setDepth(1000);

  this.tweens.add({
    targets: fadeOut,
    alpha: 1,
    duration: 1000,
    ease: 'Power2',
    onComplete: () => {
      this.scene.start('DoorScene');
    }
  });
}

